import{_ as r,o as a,c as o,aj as d}from"./chunks/framework.Cn87zHeG.js";const e="/onerobot-H1/images/faq/ctrl1.webp",n="/onerobot-H1/images/faq/ctrl2.webp",_=JSON.parse('{"title":"手柄遥操作","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"faq/controller.md","filePath":"faq/controller.md"}'),l={name:"faq/controller.md"};function s(i,t,h,c,q,g){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="手柄遥操作" tabindex="-1">手柄遥操作 <a class="header-anchor" href="#手柄遥操作" aria-label="Permalink to &quot;手柄遥操作&quot;">​</a></h1><p><a href="/onerobot-H1/downloads/faq/controller-guide.pdf">下载《手柄外观结构按键功能及使用说明》（PDF）</a></p><h2 id="q6" tabindex="-1">Q6. 手柄怎么开机？ <a class="header-anchor" href="#q6" aria-label="Permalink to &quot;Q6. 手柄怎么开机？ {#q6}&quot;">​</a></h2><p>按 <strong>Play（HOME）</strong> 键开机。</p><h2 id="q7" tabindex="-1">Q7. 手柄怎么和机器人重新配对？ <a class="header-anchor" href="#q7" aria-label="Permalink to &quot;Q7. 手柄怎么和机器人重新配对？ {#q7}&quot;">​</a></h2><ol><li>机器人<strong>开机</strong>并靠近机器人。</li><li>让手柄处于<strong>关机</strong>状态（若未关机，按 <strong>Back + B</strong> 直到灯灭）。</li><li>按住 <strong>Play + A</strong>（新手柄：长按 <strong>HOME</strong>）直到指示灯亮起，<strong>手柄震动即代表配对成功</strong>。</li></ol><h2 id="q8" tabindex="-1">Q8. 手柄各按键都是什么功能？ <a class="header-anchor" href="#q8" aria-label="Permalink to &quot;Q8. 手柄各按键都是什么功能？ {#q8}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>功能</th></tr></thead><tbody><tr><td>Play（HOME）</td><td>手柄开机</td></tr><tr><td>Start</td><td>进入主臂控制从臂模式 / 重置姿态</td></tr><tr><td>Back</td><td>退出当前模式，进入待机状态（<strong>并校准升降和头部</strong>）</td></tr><tr><td>Y</td><td>身体上升</td></tr><tr><td>A</td><td>身体下降</td></tr><tr><td>按住 LB（左红键）</td><td>左夹爪张开（松开恢复夹紧）</td></tr><tr><td>按住 RB（右红键）</td><td>右夹爪张开（松开恢复夹紧）</td></tr><tr><td>按一下 LT（左红键）</td><td>加速</td></tr><tr><td>按一下 RT（右红键）</td><td>减速</td></tr><tr><td>方向键 前 / 后</td><td>底盘前进 / 后退</td></tr><tr><td>方向键 左 / 右</td><td>底盘原地逆时针 / 顺时针旋转</td></tr><tr><td>右摇杆</td><td>上下左右控制头部对应转动</td></tr></tbody></table><p><img src="'+e+'" alt="手柄外观与按键布局（新款）"></p><p><img src="'+n+'" alt="旧款手柄外观"></p><h2 id="q9" tabindex="-1">Q9. LT / RT 加减速控制的是升降还是底盘？ <a class="header-anchor" href="#q9" aria-label="Permalink to &quot;Q9. LT / RT 加减速控制的是升降还是底盘？ {#q9}&quot;">​</a></h2><p>取决于按之前你正在控制的是<strong>升降</strong>还是<strong>底盘</strong>——<strong>两者独立调节速度</strong>。也就是说，控制升降时调的是升降速度，控制底盘时调的是底盘速度。</p><h2 id="q10" tabindex="-1">Q10. 手柄使用有哪些注意事项？ <a class="header-anchor" href="#q10" aria-label="Permalink to &quot;Q10. 手柄使用有哪些注意事项？ {#q10}&quot;">​</a></h2><ul><li><strong>主臂、从臂、手柄、笔记本是配套使用的</strong>，不可拆分使用，也不要借用其它测试设备。</li><li>操作时<strong>禁止重复按同一个按键</strong>——会造成指令重复下发，导致机器人大幅度抖动。</li><li><strong>禁止按未知功能的按键。</strong></li></ul><h2 id="q11" tabindex="-1">Q11. 手柄没反应 / 配不上怎么办？ <a class="header-anchor" href="#q11" aria-label="Permalink to &quot;Q11. 手柄没反应 / 配不上怎么办？ {#q11}&quot;">​</a></h2><p>先按 <strong>Back + B</strong> 让手柄关机（灯灭），确认机器人已开机且手柄靠近机器人，再按 Q7 的步骤重新配对。</p>',16)])])}const b=r(l,[["render",s]]);export{_ as __pageData,b as default};
